export default function prepareSpeechFile({ file }) {
  if (
    !file ||
    typeof file !== "object" ||
    typeof file.name !== "string" ||
    !file.name.trim() ||
    typeof file.mimetype !== "string" ||
    typeof file.s3url !== "string" ||
    !/^https?:\/\/[^\s]+$/.test(file.s3url)
  )
    throw new Error("The speech service returned an invalid downloadable file.");
  const mimetype = file.mimetype.split(";")[0].trim().toLowerCase();
  if (!["audio/mpeg", "audio/mp3", "application/octet-stream"].includes(mimetype))
    throw new Error("The speech response is not an MP3 audio file.");
  return { file: { name: file.name, mimetype, url: file.s3url } };
}

