export default function validateEnglishSpeechText({ text }) {
  if (typeof text !== "string" || !text.trim())
    throw new Error("The translation returned no English text.");
  const englishText = text.trim();
  if (Array.from(englishText).length > 10000)
    throw new Error("The English translation exceeds the 10000-character speech limit.");
  return { englishText };
}

